const files = {"/": {"contentType": "text/html; charset=utf-8", "base64": ""}, "/index.html": {"contentType": "text/html; charset=utf-8", "base64": ""}, "/styles.css": {"contentType": "text/css; charset=utf-8", "base64": ""}, "/app.js": {"contentType": "text/javascript; charset=utf-8", "base64": ""}, "/manifest.webmanifest": {"contentType": "application/manifest+json; charset=utf-8", "base64": ""}, "/service-worker.js": {"contentType": "text/javascript; charset=utf-8", "base64": ""}, "/assets/icon.svg": {"contentType": "image/svg+xml", "base64": ""}, "/assets/icon-192.png": {"contentType": "image/png", "base64": ""}, "/assets/icon-512.png": {"contentType": "image/png", "base64": ""}, "/assets/icon-maskable-512.png": {"contentType": "image/png", "base64": ""}};

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname.endsWith("/") && url.pathname !== "/" ? url.pathname.slice(0, -1) : url.pathname;
    const file = files[path] || files["/"];
    return new Response(decodeBase64(file.base64), {
      headers: {
        "content-type": file.contentType,
        "cache-control": path === "/service-worker.js" ? "no-cache" : "public, max-age=300",
      },
    });
  },
};
